/* real flag images via reliable CDN, emoji fallback if offline */
const PICIMG={vietnam:'vn',england:'gb-eng',america:'us',usa:'us',australia:'au',japan:'jp',france:'fr',canada:'ca',singapore:'sg',korea:'kr',thailand:'th'};
function cleanW(w){return (w||'').toLowerCase().replace(/^(a |an |the |to |by )/,'').trim()}
function picOf(w){if(!w)return'';return PICDICT[cleanW(w)]||PICDICT[w.toLowerCase()]||''}
function imgOf(w){const k=cleanW(w);return PICIMG[k]?('https://flagcdn.com/w320/'+PICIMG[k]+'.png'):''}
function imgFail(el){el.parentNode.innerHTML='<span class="em">'+(el.getAttribute('data-em')||'🖼️')+'</span>'}
function picBox(w,small){const img=imgOf(w),em=picOf(w);
  if(img)return `<div class="picbox${small?' small':''}"><img class="picimg" src="${img}" alt="" data-em="${em||'🖼️'}" onerror="imgFail(this)"></div>`;
  return em?`<div class="picbox${small?' small':''}"><span class="em">${em}</span></div>`:'';}
function hasPic(w){return !!(picOf(w)||imgOf(w))}

