function g10Rel(){const[s,a,d]=rnd(G10R);return mkQ(s,a,[a,...d],"Có dấu phẩy → không dùng that; whose + N (sở hữu); where (nơi), when (thời gian).");}
const G10C=[["If people used public transport more, the air ___ cleaner.","would be",["will be","is","was"]],["If she ___ the scholarship, she will study abroad.","gets",["will get","got","would get"]],["If I had known about the workshop, I ___ it.","would have joined",["would join","will join","joined"]],["We would save energy if we ___ off unused lights.","turned",["turn","will turn","would turn"]],["Unless we protect forests, wildlife ___ .","will suffer",["would suffer","suffers","suffered"]],["If the concert ___ cancelled, we would have gone.","hadn't been",["wasn't","isn't","weren't"]]];
function g10If(){const[s,a,d]=rnd(G10C);return mkQ(s,a,[a,...d],"Loại 1: HT đơn + will · Loại 2: QK đơn + would · Loại 3: had V3 + would have V3.");}
const G10L=[["___ the heavy traffic, she arrived on time.","Despite",["Although","Because","So"]],["Music helps us relax; ___, it improves our mood.","moreover",["although","despite","because of"]],["___ he practised a lot, he did not win the contest.","Although",["Despite","Because of","So"]],["The show was cancelled ___ the bad weather.","because of",["because","although","however"]],["She loves classical music ___ her brother prefers rock.","whereas",["because","so","despite"]],["Recycling saves money. ___ , it protects the planet.","In addition",["Although","Because","Despite"]]];
function g10Link(){const[s,a,d]=rnd(G10L);return mkQ(s,a,[a,...d],"Although/Because + mệnh đề · Despite/Because of + N · Moreover/In addition/However đứng đầu câu.");}

