/* --- build a fresh quiz set every round --- */
function buildQuizSet(g,topicId){
  let qs=[];
  if(topicId==='all'){
    qs=pickN(DATA[g].quiz,4);
    pickN(GENQ[g]||[],2).forEach(f=>qs.push(f()));
    qs.push(genVocabMCQ(g));qs.push(genOdd(g));qs.push(genPicMCQ(g));
  }else{
    const t=DATA[g].topics.find(x=>x.id===topicId);
    qs.push(genVocabMCQ(g,t),genVocabMCQ(g,t),genPicMCQ(g,t),genOdd(g,t),genSpell(g,t));
    pickN(GENQ[g]||[],3).forEach(f=>qs.push(f()));
  }
  return shuffle(qs);
}
/* --- random story → listening & reading --- */
function qPool(q,correct,pool){
  const o=shuffle([correct,...pickN(pool.filter(x=>x!==correct),3)]);
  return{q,o,a:o.indexOf(correct)};
}
